using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
public static class CemeteryTextureFix {public static string Run(){string dir="Assets/Resources/ExpeditionEnemies/Cemetery/";foreach(var p in Directory.GetFiles(dir,"*.mat")){string name=Path.GetFileNameWithoutExtension(p);string source=null;if(name.StartsWith("HeadSpider_"))source=name.Contains("Eye")?"Assets/03_Models/Cemetery/HeadSpider_FREE/Eyes.png":"Assets/03_Models/Cemetery/HeadSpider_FREE/HeadSpider.png";if(name.StartsWith("Watcher_")){string folder="Assets/03_Models/Cemetery/The Watcher of the Hollow Eye/The Watcher of the Hollow Eye/texture/";string token=name.Contains("cabeza")?"cabeza":name.Contains("cuerpo")?"body":name.Contains("brazos")?"manos":name.Contains("piernas")?"piernas":"arma";source=Directory.GetFiles(folder,"*.png").First(f=>Path.GetFileName(f).StartsWith(token));}if(source!=null){var m=AssetDatabase.LoadAssetAtPath<Material>(p.Replace('\\','/'));m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture>(source.Replace('\\','/')));EditorUtility.SetDirty(m);}}AssetDatabase.SaveAssets();return "HeadSpider and Watcher texture slots mapped";}}
